(async () => { const sleep = ms => new Promise(r => setTimeout(r, ms));
  const openPalette = async () => { document.dispatchEvent(new KeyboardEvent('keydown', { key: 'k', ctrlKey: true, bubbles: true })); await sleep(400); return document.querySelector('.palette input'); };
  const type = async (el, v) => { el.value = v; el.dispatchEvent(new Event('input', { bubbles: true })); await sleep(300); };
  const key = (el, k, mod = false) => el.dispatchEvent(new KeyboardEvent('keydown', { key: k, ctrlKey: mod, bubbles: true }));
  const groups = () => Object.fromEntries([...document.querySelectorAll('.palette [role=group]')].map(g => [g.querySelector('.group-title span').textContent.trim(), [...g.querySelectorAll('.item-label')].map(e => e.textContent.trim())]));
  const names = () => [...document.querySelectorAll('.steps .step-name')].map(e => e.textContent.trim());
  const field = await openPalette(); await type(field, 'caeser');
  const g = groups();
  const ok = (g['Best matches'] ?? []).includes('Caesar Box Cipher') && (g['Also known as'] ?? []).includes('ROT13') && !(g['Also known as'] ?? []).includes('JWT parser') && (g['Actions'] ?? []).some(label => /^Add .+ to the recipe$/.test(label));
  return ok || g;
})()

